	public static string AddAbility(string rotationNumber, string index, string abilityName, string spellID, string action, string testCode, string recastDelay, string targetCast, string cancelChannel, string LuaBefore, string LuaAfter)
	{
		string text = "function pqrFunc" + index + "() " + testCode + " end";
		string text2 = " function pqrFuncBefore" + index + "() " + LuaBefore + " end";
		string text3 = " function pqrFuncAfter" + index + "() " + LuaAfter + " end";
		string text5 = (abilityName ?? "").Replace("\\", "\\\\").Replace("\"", "\\\"");
		string text4 = "PQR_AddAbility(" + rotationNumber + ", " + index + ", \"" + text5 + "\", " + spellID + ", \"" + action + "\", pqrFunc" + index + ", " + recastDelay + ", \"" + targetCast.ToLower().Trim() + "\", " + cancelChannel.ToLower().Trim() + ", pqrFuncBefore" + index + ", pqrFuncAfter" + index + ")";
		return text + " " + text2 + " " + text3 + " " + text4;
	}

	public static string PreStartupBot(bool showChat, bool enableDebug, bool requireCombat, bool rotationDesignation, double refreshRate, double interruptDelay)
	{
		string text = "";
		text = text + " PQR_ShowChat = " + showChat.ToString().ToLower();
		text = text + " PQR_DebugEnabled = " + enableDebug.ToString().ToLower();
		text = text + " PQR_RequireCombat = " + requireCombat.ToString().ToLower();
		text = text + " PQR_RotationDesignation = " + rotationDesignation.ToString().ToLower();
		text = text + " PQR_StartRotationSound = \"" + GlobalSettings.Sound_StartRotation.Trim() + "\"";
		text = text + " PQR_ChangeRotationSound = \"" + GlobalSettings.Sound_ChangeRotation.Trim() + "\"";
		text = text + " PQR_StopRotationSound = \"" + GlobalSettings.Sound_StopRotation.Trim() + "\"";
		text = text + " PQR_StartInterruptSound = \"" + GlobalSettings.Sound_StartInterrupt.Trim() + "\"";
		text = text + " PQR_StopInterruptSound = \"" + GlobalSettings.Sound_StopInterrupt.Trim() + "\"";
		if (refreshRate >= 20.0 && refreshRate <= 1000.0)
		{
			object obj = text;
			text = string.Concat(obj, "PQR_ChangeInterval(", refreshRate, ")");
		}
		else
		{
			text += "PQR_ChangeInterval(100)";
		}
		if (interruptDelay > 0.0 && interruptDelay <= 1000.0)
		{
			return text + " PQR_InterruptDelay = " + interruptDelay;
		}
		return text + " PQR_InterruptDelay = 0";
	}

	public static string StartupBot(bool EnableInterrupt, bool interruptModeChange, bool interruptAll, bool SmartKeyMode, bool changeRotation, string rotationName)
	{
		string text = "";
		text = text + " PQR_InterruptAllSpells = " + interruptAll.ToString().ToLower();
		if (!EnableInterrupt)
		{
			text += " PQR_EnableInterrupt(true)";
		}
		else if (interruptModeChange)
		{
			text += " PQR_EnableInterrupt()";
		}
		if (changeRotation)
		{
			text = text + " PQR_ManualMode = " + SmartKeyMode.ToString().ToLower();
			if (rotationName == "")
			{
				text += " PQR_EnableBot(\"\")";
			}
			else if (rotationName == "* Manual")
			{
				text = text + " PQR_EnableBot(\"" + rotationName + "\")";
			}
			else
			{
				string text2 = rotationName.Substring(rotationName.LastIndexOf("(") + 1, rotationName.LastIndexOf(")") - rotationName.LastIndexOf("(") - 1);
				rotationName = rotationName.Substring(0, rotationName.Length - (rotationName.Length - rotationName.LastIndexOf(" (")));
				string text3 = text;
				text = text3 + " PQR_EnableBot(\"" + rotationName + "^&*" + text2 + "\")";
			}
		}
		return text;
	}

	public static string strCastNextFunction(string functionName)
	{
		if (functionName.Replace(" ", "") == "")
		{
			return "nil";
		}
		string text = "\r\n                SetCVar(\"violenceLevel\", 2)\r\n\r\n                function %FNAME%(castNextRotation)\r\n                    if castNextRotation ~= nil then\r\n                        if tonumber(castNextRotation) ~= nil then\r\n                            SetCVar(\"violenceLevel\", castNextRotation + 5)\r\n                        end\r\n                    end\r\n                end";
		return text.Replace("%FNAME%", functionName);
	}
}
